21	    private static void sortValidated(int[] values) {
22	        if (values.length < 2) {
23	            return;
24	        }
25	
26	        SortWorkspace workspace = new SortWorkspace(values.length);
27	        int maxValue = findMax(values);
28	
29	        for (int exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
30	            countingSortByDigit(values, workspace, exponent);
31	        }
32	    }
