34	    private static int[] requireSupportedValues(int[] values) {
35	        Objects.requireNonNull(values, "values");
36	
37	        for (int value : values) {
38	            if (value < 0) {
39	                throw new IllegalArgumentException(
40	                    "Radix sort only supports non-negative integers."
41	                );
42	            }
43	        }
44	
45	        return values;
46	    }
