58	    private static void countingSortByDigit(
59	        int[] values,
60	        SortWorkspace workspace,
61	        int exponent
62	    ) {
63	        Arrays.fill(workspace.counts, 0);
64	
65	        for (int value : values) {
66	            workspace.counts[digitAt(value, exponent)]++;
67	        }
68	
69	        for (int digit = 1; digit < RADIX; digit++) {
70	            workspace.counts[digit] += workspace.counts[digit - 1];
71	        }
72	
73	        for (int index = values.length - 1; index >= 0; index--) {
74	            int value = values[index];
75	            int digit = digitAt(value, exponent);
76	            workspace.output[--workspace.counts[digit]] = value;
77	        }
78	
79	        System.arraycopy(workspace.output, 0, values, 0, values.length);
80	    }
